-- Resources content for On Air's Automation tab and station IDs (CLAUDE.md,
-- "Resources stay in step with the code"). Content only; no schema change.
-- Automated hours became their own "Automation" tab, and the Station IDs page
-- was removed: the hourly legal ID is pinned on the clock page like any other
-- pinned content. Its guide keeps its slug and now explains pinning the ID on
-- the clock page, shown in Help there.

select private.rc_release_guide(
  p_slug => 'log-automated-hours',
  p_tool_key => 'log',
  p_title => 'Automation',
  p_summary => 'When no one is in the studio: weekly automated hours and one-time changes, and what they mean for credits.',
  p_screen_keys => array['log.automated-hours'],
  p_sort_order => 45,
  p_version_note => 'Automation has its own tab',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every hour is hosted unless it's listed on this page. In automated hours no one is in the studio, so DAD plays that hour's underwriting credits. Open it from the "},{"type":"text","text":"Automation","marks":[{"type":"bold"}]},{"type":"text","text":" tab."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Weekly hours"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"+ Weekly hours","marks":[{"type":"bold"}]},{"type":"text","text":" for the routine ones, such as overnights from 8:00 PM to 5:00 AM. Pick the days, the times, and the date they start."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An end time at or before the start runs past midnight. The early-morning part belongs to the day the hours started, so Saturday 8:00 PM – 5:00 AM covers early Sunday."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Weekly hours can cover a whole program or just some of its hours. The "},{"type":"text","text":"Programs in these hours","marks":[{"type":"bold"}]},{"type":"text","text":" column shows what's on the air then."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"One-time changes"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"+ One-time change","marks":[{"type":"bold"}]},{"type":"text","text":" for a holiday, a host out, or a special. Choose "},{"type":"text","text":"Automated","marks":[{"type":"bold"}]},{"type":"text","text":" to automate hours that are normally hosted, or "},{"type":"text","text":"Live","marks":[{"type":"bold"}]},{"type":"text","text":" to host hours that are normally automated."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A one-time change wins over the weekly hours. One-time changes can't overlap each other."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Midnight to midnight covers whole days: Thanksgiving is Thursday 12:00 AM until Friday 12:00 AM."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Week and month"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The week view draws each day's automated hours over the programs on the air. Grey is weekly, dashed amber is automated once, and dashed blue is live once."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The month view shows each day's automated hours. Pick a day to see its week."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A credit in automated hours needs copy with a DAD cut, since DAD plays it. A live read qualifies through its recorded version. Auto-fill leaves those breaks to copy that has one, and placing cut-less copy there is refused."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only the program director can change automated hours. Nothing is deleted: removing hours or a change takes it off the schedule."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'log-read-a-clock',
  p_tool_key => 'log',
  p_title => 'Read a clock',
  p_summary => 'The timeline and ring diagrams, hours of a longer shift, floating breaks, versions, and pinned content.',
  p_screen_keys => array['log.clock'],
  p_sort_order => 10,
  p_version_note => 'Traffic can pin content here',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Open a clock from the program that airs on it: on the program's page, select "},{"type":"text","text":"Open clock","marks":[{"type":"bold"}]},{"type":"text","text":". The link at the top left of the clock's page goes back to that program."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Timeline and Ring"}]},{"type":"paragraph","content":[{"type":"text","text":"The diagram shows one hour of the clock. Switch between "},{"type":"text","text":"Timeline","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Ring","marks":[{"type":"bold"}]},{"type":"text","text":" at the top right of the diagram; both behave the same way."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The network's structure comes first: segments, newscasts (dark), and promos and credits. WUWF's local opportunities are marked in blue: a dashed outline for optional, solid for required."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hover over or tab to a slot to read its name, times, and length. Select a slot to fix it in the side panel and the slot list."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Slots list lists every slot. Hovering over a row highlights that slot in the diagram; selecting a row shows it in the side panel."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Shifts longer than an hour"}]},{"type":"paragraph","content":[{"type":"text","text":"When a program airs for more than an hour, the clock repeats every hour. Use the arrows beside "},{"type":"text","text":"Hour 1 of 2","marks":[{"type":"bold"}]},{"type":"text","text":" to step through the hours. The network structure is the same in each hour, but pinned content can differ, and a small number on a local slot shows how many items are pinned for the hour you're looking at."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Floating breaks"}]},{"type":"paragraph","content":[{"type":"text","text":"A break whose position isn't fixed appears as a shaded window. A dashed edge can move and a solid edge is fixed; the darker area is always part of the break. Select it to see when it can start and end and how long it can run."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Versions"}]},{"type":"paragraph","content":[{"type":"text","text":"Choose a version from the "},{"type":"text","text":"Version","marks":[{"type":"bold"}]},{"type":"text","text":" menu. A version can't be edited once it exists — a correction is a new version, started with "},{"type":"text","text":"+ New version","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Changing what WUWF can fill (program director)"}]},{"type":"paragraph","content":[{"type":"text","text":"Select a slot, then use the buttons in its panel: "},{"type":"text","text":"Edit eligibility","marks":[{"type":"bold"}]},{"type":"text","text":" on a local slot, or "},{"type":"text","text":"Mark eligible for local content","marks":[{"type":"bold"}]},{"type":"text","text":" on a network-only one. "},{"type":"text","text":"Remove","marks":[{"type":"bold"}]},{"type":"text","text":" takes a slot out of local eligibility."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Pinning content (program director or traffic)"}]},{"type":"paragraph","content":[{"type":"text","text":"A pin puts the same content item into a slot in every rundown made from this clock: the hourly station ID (see "},{"type":"text","text":"Station IDs","marks":[{"type":"bold"}]},{"type":"text","text":"), or a feature like BirdNote. Select a local slot, then "},{"type":"text","text":"Pin content","marks":[{"type":"bold"}]},{"type":"text","text":". Choose the item, then the hour and days. "},{"type":"text","text":"Every hour","marks":[{"type":"bold"}]},{"type":"text","text":" with no days checked covers the whole shift, every day. "},{"type":"text","text":"Remove","marks":[{"type":"bold"}]},{"type":"text","text":" under a pinned item takes the pin off."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'underwriting-dashboard',
  p_tool_key => 'underwriting',
  p_title => 'The dashboard',
  p_summary => 'What needs attention today, grouped by job: missed credits, scheduling, and affidavits.',
  p_screen_keys => array['underwriting.dashboard'],
  p_sort_order => 10,
  p_version_note => 'Station IDs moved to the clock page',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The dashboard opens on what needs attention, in three groups. Every number links to the list it counts, filtered the same way."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Missed credits"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Need a decision","marks":[{"type":"bold"}]},{"type":"text","text":": an exception with no makegood yet, or one the agency declined."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Waiting on the agency","marks":[{"type":"bold"}]},{"type":"text","text":": the order's makegoods need the agency's approval, and no answer is recorded yet."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Makegoods awaiting a break","marks":[{"type":"bold"}]},{"type":"text","text":": the next auto-fill places these first."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Scheduling"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Units not yet scheduled","marks":[{"type":"bold"}]},{"type":"text","text":": open periods on active contracts that auto-fill hasn't reached yet."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Capacity conflicts","marks":[{"type":"bold"}]},{"type":"text","text":": lines that can't be placed in the next 14 days, listed below with what's blocking each one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"To record in DAD","marks":[{"type":"bold"}]},{"type":"text","text":": messages under a new DAD cut that production hasn't marked recorded yet."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Affidavits"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"To generate","marks":[{"type":"bold"}]},{"type":"text","text":": contracts with aired credits not yet covered by an affidavit."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Awaiting your signature","marks":[{"type":"bold"}]},{"type":"text","text":": generated affidavits ready to sign. Only underwriting managers see this one."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Auto-fill everything","marks":[{"type":"bold"}]},{"type":"text","text":" in the right-hand column to fill every active contract's open periods, makegoods first."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If you can open On Air, "},{"type":"text","text":"Log of record","marks":[{"type":"bold"}]},{"type":"text","text":" in the right-hand column shows whether the DAD log is released for today and the next two days."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'log-station-ids',
  p_tool_key => 'log',
  p_title => 'Station IDs',
  p_summary => 'Pinning the hourly legal ID on a clock, so every hour has one.',
  p_screen_keys => array['log.clock'],
  p_sort_order => 44,
  p_version_note => 'Pinned on the clock page',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The station identifies itself every hour, as close to the top of the hour as it can, at a natural break. The legal ID is pinned on each clock's page, the same way as any other pinned content, and goes into every rundown made from that clock."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Pin the station ID"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open the program, then "},{"type":"text","text":"Open clock","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select the slot that takes the legal ID, usually the last break before the top of the hour."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Pin content","marks":[{"type":"bold"}]},{"type":"text","text":" and choose the station ID. Leave the hour on "},{"type":"text","text":"Every hour","marks":[{"type":"bold"}]},{"type":"text","text":" and no days checked, then select "},{"type":"text","text":"Pin content","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If an hour on the clock in effect has no legal ID, a warning at the top of the clock's page says which."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If no slot takes a legal ID yet, the warning says so. The program director marks the slot eligible for a legal ID first."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A new clock version starts without pins, so pin the ID again on the new version."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A pinned ID goes into rundowns made from then on. Rundowns already made keep what they have."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The program director or traffic can pin and remove the ID."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-05-log-automation-and-station-ids',
  p_tool_key => 'log',
  p_released_on => '2026-10-05',
  p_title => 'Automation gets its own tab, and station IDs are pinned on the clock',
  p_guide_slugs => array['log-automated-hours', 'log-station-ids', 'log-read-a-clock', 'underwriting-dashboard'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Automated hours have their own tab, Automation, beside Programs. The Station IDs page is gone: the hourly legal ID is pinned on each clock's page like any other pinned content, and the clock page warns when an hour has no ID. Traffic can now pin content from the clock page as well as the program director."}]}]}$body$
);
